import { collection, addDoc, doc, getDoc, updateDoc, Timestamp } from "firebase/firestore";
import { db } from "../../firebase"; 
import { calculateCarbonMetrics } from "../../utils/carbonCalculator"; 

const TARGET_FOOTPRINT = 20; // Set an ideal daily carbon goal
const CREDITS_PER_KG = 0.5; // How many credits per kg CO₂

const saveCarbonData = async (userId, formData) => {
  console.log("🔄 Starting data submission...");

  try {
    const selectedDate = new Date(formData.date);
    const createdAt = Timestamp.fromDate(selectedDate);

    console.log("📅 Date selected:", selectedDate.toISOString());

    // Convert input values to numbers (except date)
    const inputData = Object.keys(formData).reduce((acc, key) => {
      if (key !== "date") {
        acc[key] = parseFloat(formData[key]) || 0;
      }
      return acc;
    }, {});

    console.log("📊 Processed input data:", inputData);

    // Calculate carbon footprint & progress
    const carbonData = calculateCarbonMetrics(inputData);
    const dailyCredits = carbonData.totalCarbon * CREDITS_PER_KG; // ✅ Award credits based on footprint

    console.log("🌍 Carbon footprint calculated:", carbonData.totalCarbon, "kg CO₂");
    console.log("💰 Credits earned for today:", dailyCredits);

    // Reference user doc in Firestore
    const userRef = doc(db, "users", userId);
    const userSnap = await getDoc(userRef);

    let totalCredits = dailyCredits; // Default to daily credits if user has no stored data

    if (userSnap.exists()) {
      const userData = userSnap.data();
      totalCredits += userData.credits || 0; // ✅ Add new credits to existing ones

      console.log("📂 Existing user data found. Previous credits:", userData.credits || 0);
    } else {
      console.log("🆕 No existing user data. Starting fresh.");
    }

    console.log("🔄 Updating total credits:", totalCredits);

    // Save footprint data to "carbonFootprint" collection
    await addDoc(collection(db, "carbonFootprint"), {
      userId,
      ...inputData,
      totalCarbon: carbonData.totalCarbon,
      creditsEarned: dailyCredits,
      createdAt,
    });

    console.log("✅ Carbon footprint data saved in Firestore!");

    // Update the user's total credits in Firestore
    await updateDoc(userRef, {
      credits: totalCredits, // ✅ Store the updated total
      lastUpdated: createdAt,
    });

    console.log("✅ User credits updated successfully!");

    return { success: true, message: "Data saved successfully!", totalCredits };
  } catch (error) {
    console.error("❌ Error saving data:", error);
    return { success: false, message: "Failed to save data. Try again." };
  }
};
